        }
      }
    }catch(error){
      if(inspected&&['ENOENT','ESRCH'].includes(error.code))observation={state:'ENDED',basis:'ORIGINAL_PROCESS_ABSENT'};
      else observation={state:'UNKNOWN',basis:safeCode(error.code,'ORIGINAL_PROCESS_NOT_OBSERVED')};
